import{_ as i,a0 as e,w as r,s as a,ao as l,I as o,x as n,a1 as p,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"Linux有问必答： 当使用代理服务器连接互联网时如何安装 Ubuntu 桌面版 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答： 当使用代理服务器连接互联网时如何安装 Ubuntu 桌面版 | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答： 当使用代理服务器连接互联网时如何安装 Ubuntu 桌面版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答： 当使用代理服务器连接互联网时如何安装 Ubuntu 桌面版 | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151019 Linux FAQs with Answers--How to install Ubuntu desktop behind a proxy","title":"Linux有问必答： 当使用代理服务器连接互联网时如何安装 Ubuntu 桌面版","tag":"201511","desc":""},"relativePath":"201511/20151019 Linux FAQs with Answers--How to install Ubuntu desktop behind a proxy.md","filePath":"[post].md"}'),b={name:"201511/20151019 Linux FAQs with Answers--How to install Ubuntu desktop behind a proxy.md"};function d(m,t,c,x,_,f){const u=e("Link");return r(),a("div",null,[t[13]||(t[13]=l(`<h1 id="linux有问必答-当使用代理服务器连接互联网时如何安装-ubuntu-桌面版" tabindex="-1">Linux有问必答： 当使用代理服务器连接互联网时如何安装 Ubuntu 桌面版 <a class="header-anchor" href="#linux有问必答-当使用代理服务器连接互联网时如何安装-ubuntu-桌面版" aria-label="Permalink to “Linux有问必答： 当使用代理服务器连接互联网时如何安装 Ubuntu 桌面版”">​</a></h1><blockquote><p><strong>提问：</strong> 我的电脑连接到的公司网络是使用HTTP代理连上互联网的。当我想使用CD-ROM安装Ubuntu时，安装在尝试获取文件时被停滞了，可能是由于代理的原因。然而问题是Ubuntu的安装程序从来没有在安装过程中提示我配置代理。我该怎样通过代理服务器安装Ubuntu桌面版？</p></blockquote><p>不像Ubuntu服务器版，Ubuntu桌面版的安装非常自动化，没有留下太多的自定义空间，就像自定义磁盘分区，手动网络设置，包选择等等。虽然这种简单的，一键安装被认为是用户友好的，但却是那些寻找“高级安装模式”来定制自己的Ubuntu桌面安装的用户不希望的。</p><p>除此之外，默认的Ubuntu桌面版安装器的一个大问题是缺少代理设置。如果你电脑在代理后面，你会看到Ubuntu在准备下载文件的时候停滞了。</p><p><img src="https://c2.staticflickr.com/6/5683/22195372232_cea81a5e45_c.jpg" alt=""></p><p>这篇文章描述了如何解除Ubuntu安装限制以及<strong>如何通过代理服务器安装Ubuntu桌面</strong>。</p><p>基本的想法是这样的。首先启动到live Ubuntu桌面中而不是直接启动Ubuntu安装器，配置代理设置并且手动在live Ubuntu中启动Ubuntu安装器。下面是步骤。</p><p>从Ubuntu桌面版CD/DVD或者USB启动后，在欢迎页面点击“Try Ubuntu”。</p><p><img src="https://c1.staticflickr.com/1/586/22195371892_3816ba09c3_c.jpg" alt=""></p><p>当你进入live Ubuntu后，点击左边的设置图标。</p><p><img src="https://c1.staticflickr.com/1/723/22020327738_058610c19d_c.jpg" alt=""></p><p>进入网络菜单。</p><p><img src="https://c2.staticflickr.com/6/5675/22021212239_ba3901c8bf_c.jpg" alt=""></p><p>手动配置代理。</p><p><img src="https://c1.staticflickr.com/1/735/22020025040_59415e0b9a_c.jpg" alt=""></p><p>接下来，打开终端。</p><p><img src="https://c2.staticflickr.com/6/5642/21587084823_357b5c48cb_c.jpg" alt=""></p><p>输入下面的命令进入root会话。</p><pre><code>$ sudo su
</code></pre><p>最后以root权限输入下面的命令。</p><pre><code># ubiquity gtk_ui
</code></pre><p>它会启动基于GUI的Ubuntu安装器。</p><p><img src="https://c1.staticflickr.com/1/723/22020025090_cc64848b6c_c.jpg" alt=""></p><p>接着完成剩余的安装。</p><p><img src="https://c1.staticflickr.com/1/628/21585344214_447020e9d6_c.jpg" alt=""></p><hr>`,26)),o("p",null,[t[1]||(t[1]=n("via: ",-1)),p(u,{href:"http://ask.xmodulo.com/install-ubuntu-desktop-behind-proxy.html"},{default:s(()=>[...t[0]||(t[0]=[n("http://ask.xmodulo.com/install-ubuntu-desktop-behind-proxy.html",-1)])]),_:1})]),o("p",null,[t[5]||(t[5]=n("作者：",-1)),p(u,{href:"http://ask.xmodulo.com/author/nanni"},{default:s(()=>[...t[2]||(t[2]=[n("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=n(" 译者：",-1)),p(u,{href:"https://github.com/geekpi"},{default:s(()=>[...t[3]||(t[3]=[n("geekpi",-1)])]),_:1}),t[7]||(t[7]=n(" 校对：",-1)),p(u,{href:"https://github.com/wxy"},{default:s(()=>[...t[4]||(t[4]=[n("wxy",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=n("本文由 ",-1)),p(u,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[8]||(t[8]=[n("LCTT",-1)])]),_:1}),t[11]||(t[11]=n(" 原创编译，",-1)),p(u,{href:"https://linux.cn/"},{default:s(()=>[...t[9]||(t[9]=[n("Linux中国",-1)])]),_:1}),t[12]||(t[12]=n(" 荣誉推出",-1))])])}const T=i(b,[["render",d]]);export{k as __pageData,T as default};
